diff --git a/src/learn.rs b/src/learn.rs
index c2ff88b..24888ae 100644
--- a/src/learn.rs
+++ b/src/learn.rs
@@ -89,8 +89,787 @@ where
     ) -> Self {
         let build_candidates = || {
             // FRONTIER_EDIT_BEGIN: candidate generation
-            let _ = (egraph, learn_constants, max_arity, co_occurrences);
-            todo!("library candidate generation is not implemented")
+            use std::collections::HashMap;
+            use std::convert::TryInto;
+            use std::hash::{BuildHasherDefault, Hasher};
+
+            /// A small multiplicative hasher for integer keys.
+            #[derive(Default, Clone, Copy)]
+            struct FxHasher(u64);
+
+            impl FxHasher {
+                #[inline]
+                fn add(&mut self, word: u64) {
+                    self.0 = (self.0.rotate_left(5) ^ word).wrapping_mul(0x517c_c1b7_2722_0a95);
+                }
+            }
+
+            impl Hasher for FxHasher {
+                fn finish(&self) -> u64 {
+                    self.0
+                }
+                fn write(&mut self, bytes: &[u8]) {
+                    let mut chunks = bytes.chunks_exact(8);
+                    for chunk in &mut chunks {
+                        self.add(u64::from_le_bytes(chunk.try_into().unwrap()));
+                    }
+                    for &byte in chunks.remainder() {
+                        self.add(u64::from(byte));
+                    }
+                }
+                fn write_u32(&mut self, i: u32) {
+                    self.add(u64::from(i));
+                }
+                fn write_u64(&mut self, i: u64) {
+                    self.add(i);
+                }
+                fn write_usize(&mut self, i: usize) {
+                    self.add(i as u64);
+                }
+            }
+
+            type FxMap<K, V> = HashMap<K, V, BuildHasherDefault<FxHasher>>;
+
+            const NONE: u32 = u32::MAX;
+            const UNVISITED: u32 = u32::MAX;
+            const EMPTY: u32 = 0;
+
+            /// Hash-consed anti-unification terms. A term is either a hole
+            /// labelled by a paired state or an operation applied to terms.
+            #[derive(Default)]
+            struct Terms {
+                op: Vec<u32>,
+                kid_start: Vec<u32>,
+                kid_len: Vec<u32>,
+                kids: Vec<u32>,
+                hole_start: Vec<u32>,
+                hole_len: Vec<u32>,
+                holes: Vec<u32>,
+                small: FxMap<(u32, u32, u32), u32>,
+                large: FxMap<Vec<u32>, u32>,
+            }
+
+            impl Terms {
+                fn holes_of(&self, t: u32) -> &[u32] {
+                    let start = self.hole_start[t as usize] as usize;
+                    &self.holes[start..start + self.hole_len[t as usize] as usize]
+                }
+
+                fn kids_of(&self, t: u32) -> &[u32] {
+                    let start = self.kid_start[t as usize] as usize;
+                    &self.kids[start..start + self.kid_len[t as usize] as usize]
+                }
+
+                fn push(&mut self, op: u32, kids: &[u32], holes: &[u32]) -> u32 {
+                    let id = self.op.len() as u32;
+                    self.op.push(op);
+                    self.kid_start.push(self.kids.len() as u32);
+                    self.kid_len.push(kids.len() as u32);
+                    self.kids.extend_from_slice(kids);
+                    self.hole_start.push(self.holes.len() as u32);
+                    self.hole_len.push(holes.len() as u32);
+                    self.holes.extend_from_slice(holes);
+                    id
+                }
+
+                fn hole(&mut self, state: u32) -> u32 {
+                    let key = (NONE, state, NONE);
+                    if let Some(&id) = self.small.get(&key) {
+                        return id;
+                    }
+                    let id = self.push(NONE, &[], &[state]);
+                    self.small.insert(key, id);
+                    id
+                }
+
+                /// Interns `op(kids)`; `holes` are the distinct holes of the
+                /// term in first-occurrence order.
+                fn node(&mut self, op: u32, kids: &[u32], holes: &[u32]) -> u32 {
+                    if kids.len() <= 2 {
+                        let key = (
+                            op,
+                            kids.get(0).copied().unwrap_or(NONE),
+                            kids.get(1).copied().unwrap_or(NONE),
+                        );
+                        if let Some(&id) = self.small.get(&key) {
+                            return id;
+                        }
+                        let id = self.push(op, kids, holes);
+                        self.small.insert(key, id);
+                        id
+                    } else {
+                        let mut key = Vec::with_capacity(kids.len() + 1);
+                        key.push(op);
+                        key.extend_from_slice(kids);
+                        if let Some(&id) = self.large.get(&key) {
+                            return id;
+                        }
+                        let id = self.push(op, kids, holes);
+                        self.large.insert(key, id);
+                        id
+                    }
+                }
+            }
+
+            /// The paired-state anti-unification problem over a dense
+            /// numbering of the e-classes (dense order follows `Id` order).
+            struct Search<'c> {
+                n: usize,
+                ids: Vec<Id>,
+                co_occurrences: &'c CoOccurrences,
+                max_arity: usize,
+                cross_arity: bool,
+                hole_if_empty: bool,
+                hole_if_distinct: bool,
+                exact_order: bool,
+                co_mode: u8,
+                class_start: Vec<u32>,
+                node_op: Vec<u32>,
+                node_kid_start: Vec<u32>,
+                node_kid_len: Vec<u32>,
+                node_kids: Vec<u32>,
+                class_simple: Vec<bool>,
+                co_cache: Vec<u8>,
+                /// Per state: `UNVISITED`, `EMPTY` or an index into the set arena.
+                value: Vec<u32>,
+                set_start: Vec<u32>,
+                set_len: Vec<u32>,
+                set_data: Vec<u32>,
+                /// Stack of anti-unifications of the states being computed.
+                scratch: Vec<u32>,
+                hole_buf: Vec<u32>,
+                terms: Terms,
+            }
+
+            impl<'c> Search<'c> {
+                fn co_occur(&mut self, s: usize) -> bool {
+                    match self.co_cache[s] {
+                        1 => false,
+                        2 => true,
+                        _ => {
+                            let (a, b) = (s / self.n, s % self.n);
+                            let ok = self.co_occurrences.may_co_occur(self.ids[a], self.ids[b]);
+                            self.co_cache[s] = if ok { 2 } else { 1 };
+                            ok
+                        }
+                    }
+                }
+
+                /// Whether state `s` is anti-unified at all.
+                fn entry_ok(&mut self, s: usize) -> bool {
+                    match self.co_mode {
+                        1 | 3 => true,
+                        2 => s / self.n == s % self.n || self.co_occur(s),
+                        _ => self.co_occur(s),
+                    }
+                }
+
+                /// Whether state `s` may be abstracted by a hole.
+                fn hole_ok(&mut self, s: usize) -> bool {
+                    self.co_mode != 3 || self.co_occur(s)
+                }
+
+                #[inline]
+                fn kid(&self, node: usize, k: usize) -> usize {
+                    self.node_kids[self.node_kid_start[node] as usize + k] as usize
+                }
+
+                /// The paired rules producing state `(a, b)`, in the order of
+                /// the product automaton's rule sets.
+                fn rules(&self, a: usize, b: usize, rules: &mut Vec<(u32, u32)>) {
+                    let (a0, a1) = (self.class_start[a] as usize, self.class_start[a + 1] as usize);
+                    let (b0, b1) = (self.class_start[b] as usize, self.class_start[b + 1] as usize);
+                    for x in a0..a1 {
+                        for y in b0..b1 {
+                            if self.cross_arity || self.node_kid_len[x] == self.node_kid_len[y] {
+                                rules.push((x as u32, y as u32));
+                            }
+                        }
+                    }
+                    if !(self.class_simple[a] && self.class_simple[b]) {
+                        let key = |&(x, y): &(u32, u32)| {
+                            let (x, y) = (x as usize, y as usize);
+                            let len = std::cmp::min(self.node_kid_len[x], self.node_kid_len[y]) as usize;
+                            let mut key = Vec::with_capacity(2 + 2 * len);
+                            key.push(self.node_op[x]);
+                            key.push(self.node_op[y]);
+                            for k in 0..len {
+                                key.push(self.kid(x, k) as u32);
+                                key.push(self.kid(y, k) as u32);
+                            }
+                            key
+                        };
+                        rules.sort_by_cached_key(key);
+                    }
+                }
+
+                #[inline]
+                fn members(&self, v: u32) -> (usize, usize) {
+                    if v == EMPTY || v == UNVISITED {
+                        (0, 0)
+                    } else {
+                        (self.set_start[v as usize] as usize, self.set_len[v as usize] as usize)
+                    }
+                }
+
+                /// Pushes every arity-respecting term `op(t1, ..., tk)` with
+                /// `ti` drawn from the anti-unifications of the `i`-th paired
+                /// children of nodes `x` and `y`.
+                fn product(&mut self, x: usize, y: usize, len: usize) {
+                    let op = self.node_op[x];
+                    let n = self.n;
+                    let mut ranges = [(0usize, 0usize); 4];
+                    let mut big: Vec<(usize, usize)> = Vec::new();
+                    for k in 0..len {
+                        let s = self.kid(x, k) * n + self.kid(y, k);
+                        let r = self.members(self.value[s]);
+                        if r.1 == 0 {
+                            return;
+                        }
+                        if len <= 4 {
+                            ranges[k] = r;
+                        } else {
+                            big.push(r);
+                        }
+                    }
+                    let ranges: &[(usize, usize)] = if len <= 4 { &ranges[..len] } else { &big };
+                    let max = self.max_arity;
+                    if len == 1 {
+                        let (st, ln) = ranges[0];
+                        for i in st..st + ln {
+                            let t = self.set_data[i];
+                            self.hole_buf.clear();
+                            self.hole_buf.extend_from_slice(self.terms.holes_of(t));
+                            let id = self.terms.node(op, &[t], &self.hole_buf);
+                            self.scratch.push(id);
+                        }
+                        return;
+                    }
+                    if len == 2 {
+                        let ((s1, l1), (s2, l2)) = (ranges[0], ranges[1]);
+                        for i in s1..s1 + l1 {
+                            let t1 = self.set_data[i];
+                            for j in s2..s2 + l2 {
+                                let t2 = self.set_data[j];
+                                self.hole_buf.clear();
+                                self.hole_buf.extend_from_slice(self.terms.holes_of(t1));
+                                let mut ok = self.hole_buf.len() <= max;
+                                if ok {
+                                    for &h in self.terms.holes_of(t2) {
+                                        if !self.hole_buf.contains(&h) {
+                                            self.hole_buf.push(h);
+                                        }
+                                    }
+                                    ok = self.hole_buf.len() <= max;
+                                }
+                                if ok {
+                                    let id = self.terms.node(op, &[t1, t2], &self.hole_buf);
+                                    self.scratch.push(id);
+                                }
+                            }
+                        }
+                        return;
+                    }
+                    let mut index: Vec<usize> = ranges.iter().map(|r| r.0).collect();
+                    let mut kids = vec![0u32; len];
+                    'outer: loop {
+                        self.hole_buf.clear();
+                        let mut ok = true;
+                        for i in 0..len {
+                            let t = self.set_data[index[i]];
+                            kids[i] = t;
+                            for &h in self.terms.holes_of(t) {
+                                if !self.hole_buf.contains(&h) {
+                                    self.hole_buf.push(h);
+                                }
+                            }
+                            if self.hole_buf.len() > max {
+                                ok = false;
+                                break;
+                            }
+                        }
+                        if ok {
+                            let id = self.terms.node(op, &kids, &self.hole_buf);
+                            self.scratch.push(id);
+                        }
+                        let mut i = len;
+                        loop {
+                            if i == 0 {
+                                break 'outer;
+                            }
+                            i -= 1;
+                            index[i] += 1;
+                            if index[i] < ranges[i].0 + ranges[i].1 {
+                                break;
+                            }
+                            index[i] = ranges[i].0;
+                        }
+                    }
+                }
+
+                /// Whether some rule of `(a, b)` pairs equal operations.
+                fn has_same_op(&self, a: usize, b: usize) -> bool {
+                    let (a0, a1) = (self.class_start[a] as usize, self.class_start[a + 1] as usize);
+                    let (b0, b1) = (self.class_start[b] as usize, self.class_start[b + 1] as usize);
+                    for x in a0..a1 {
+                        for y in b0..b1 {
+                            if self.node_op[x] == self.node_op[y]
+                                && (self.cross_arity || self.node_kid_len[x] == self.node_kid_len[y])
+                            {
+                                return true;
+                            }
+                        }
+                    }
+                    false
+                }
+
+                /// Moves the terms pushed since `base` into the set of `s`.
+                fn store(&mut self, s: usize, base: usize) -> u32 {
+                    let seg = &mut self.scratch[base..];
+                    seg.sort_unstable();
+                    let mut len = 0;
+                    for i in 0..seg.len() {
+                        if i == 0 || seg[i] != seg[len - 1] {
+                            seg[len] = seg[i];
+                            len += 1;
+                        }
+                    }
+                    let v = if len == 0 {
+                        EMPTY
+                    } else {
+                        self.set_start.push(self.set_data.len() as u32);
+                        self.set_len.push(len as u32);
+                        self.set_data.extend_from_slice(&self.scratch[base..base + len]);
+                        (self.set_start.len() - 1) as u32
+                    };
+                    self.scratch.truncate(base);
+                    self.value[s] = v;
+                    v
+                }
+
+                fn wants_hole(&mut self, s: usize, different: bool, empty: bool) -> bool {
+                    let (a, b) = (s / self.n, s % self.n);
+                    (different || (self.hole_if_empty && empty) || (self.hole_if_distinct && a != b))
+                        && self.hole_ok(s)
+                }
+
+                /// Computes the anti-unifications of state `s`. With cycles,
+                /// this follows the depth-first order of the product-automaton
+                /// enumeration exactly; otherwise every state's value is
+                /// independent of the visiting order.
+                fn visit(&mut self, s: usize) -> u32 {
+                    let v = self.value[s];
+                    if v != UNVISITED {
+                        return v;
+                    }
+                    self.value[s] = EMPTY;
+                    let (a, b) = (s / self.n, s % self.n);
+                    let n = self.n;
+                    let mut one = [(0u32, 0u32); 1];
+                    let mut many = Vec::new();
+                    let (a0, b0) = (self.class_start[a], self.class_start[b]);
+                    let rules: &[(u32, u32)] = if self.class_start[a + 1] - a0 == 1 && self.class_start[b + 1] - b0 == 1 {
+                        if self.cross_arity || self.node_kid_len[a0 as usize] == self.node_kid_len[b0 as usize] {
+                            one[0] = (a0, b0);
+                            &one[..]
+                        } else {
+                            &one[..0]
+                        }
+                    } else {
+                        self.rules(a, b, &mut many);
+                        &many
+                    };
+                    if self.exact_order {
+                        if !self.entry_ok(s) {
+                            return EMPTY;
+                        }
+                        let base = self.scratch.len();
+                        let mut different = false;
+                        for &(x, y) in rules {
+                            let (x, y) = (x as usize, y as usize);
+                            if self.node_op[x] == self.node_op[y] {
+                                let len = std::cmp::min(self.node_kid_len[x], self.node_kid_len[y]) as usize;
+                                if len == 0 {
+                                    let id = self.terms.node(self.node_op[x], &[], &[]);
+                                    self.scratch.push(id);
+                                } else {
+                                    for k in 0..len {
+                                        self.visit(self.kid(x, k) * n + self.kid(y, k));
+                                    }
+                                    self.product(x, y, len);
+                                }
+                            } else {
+                                different = true;
+                            }
+                        }
+                        if self.wants_hole(s, different, self.scratch.len() == base) {
+                            let id = self.terms.hole(s as u32);
+                            self.scratch.push(id);
+                        }
+                        self.store(s, base)
+                    } else {
+                        let mut productive = false;
+                        let mut different = false;
+                        for &(x, y) in rules {
+                            let (x, y) = (x as usize, y as usize);
+                            if self.node_op[x] == self.node_op[y] {
+                                let len = std::cmp::min(self.node_kid_len[x], self.node_kid_len[y]) as usize;
+                                let mut all = true;
+                                for k in 0..len {
+                                    if self.visit(self.kid(x, k) * n + self.kid(y, k)) == EMPTY {
+                                        all = false;
+                                    }
+                                }
+                                productive |= all;
+                            } else {
+                                different = true;
+                            }
+                        }
+                        let hole = different || self.hole_if_empty || (self.hole_if_distinct && a != b);
+                        if !(productive || hole) || !self.entry_ok(s) {
+                            return EMPTY;
+                        }
+                        let base = self.scratch.len();
+                        for &(x, y) in rules {
+                            let (x, y) = (x as usize, y as usize);
+                            if self.node_op[x] == self.node_op[y] {
+                                let len = std::cmp::min(self.node_kid_len[x], self.node_kid_len[y]) as usize;
+                                if len == 0 {
+                                    let id = self.terms.node(self.node_op[x], &[], &[]);
+                                    self.scratch.push(id);
+                                } else {
+                                    self.product(x, y, len);
+                                }
+                            }
+                        }
+                        if self.wants_hole(s, different, self.scratch.len() == base) {
+                            let id = self.terms.hole(s as u32);
+                            self.scratch.push(id);
+                        }
+                        self.store(s, base)
+                    }
+                }
+            }
+
+            // Dense class numbering in `Id` order.
+            let mut ids: Vec<Id> = egraph.classes().map(|class| class.id).collect();
+            ids.sort_unstable();
+            let n = ids.len();
+            let mut dense = vec![NONE; ids.last().map_or(0, |&id| usize::from(id) + 1)];
+            for (i, &id) in ids.iter().enumerate() {
+                dense[usize::from(id)] = i as u32;
+            }
+
+            // Operations numbered in `Op` order.
+            let mut ops: Vec<Op> = egraph
+                .classes()
+                .flat_map(|class| class.iter().map(|node| node.operation().clone()))
+                .collect();
+            ops.sort();
+            ops.dedup();
+
+            // E-nodes of each class sorted like the automaton's rules.
+            let mut class_start = Vec::with_capacity(n + 1);
+            let mut node_op = Vec::new();
+            let mut node_kid_start = Vec::new();
+            let mut node_kid_len = Vec::new();
+            let mut node_kids = Vec::new();
+            let mut class_simple = Vec::with_capacity(n);
+            for &id in &ids {
+                class_start.push(node_op.len() as u32);
+                let mut nodes: Vec<(u32, Vec<u32>)> = egraph[id]
+                    .iter()
+                    .map(|node| {
+                        let op = ops.binary_search(node.operation()).unwrap() as u32;
+                        let kids = node
+                            .children()
+                            .iter()
+                            .map(|&kid| dense[usize::from(egraph.find(kid))])
+                            .collect();
+                        (op, kids)
+                    })
+                    .collect();
+                nodes.sort();
+                nodes.dedup();
+                class_simple.push(nodes.windows(2).all(|w| w[0].0 != w[1].0));
+                for (op, kids) in nodes {
+                    node_op.push(op);
+                    node_kid_start.push(node_kids.len() as u32);
+                    node_kid_len.push(kids.len() as u32);
+                    node_kids.extend(kids);
+                }
+            }
+            class_start.push(node_op.len() as u32);
+
+            // Detect cycles among e-classes by repeatedly peeling classes
+            // whose children have all been peeled.
+            let mut pending = vec![0u32; n];
+            let mut parents: Vec<Vec<u32>> = vec![Vec::new(); n];
+            for c in 0..n {
+                for node in class_start[c] as usize..class_start[c + 1] as usize {
+                    let start = node_kid_start[node] as usize;
+                    for &kid in &node_kids[start..start + node_kid_len[node] as usize] {
+                        pending[c] += 1;
+                        parents[kid as usize].push(c as u32);
+                    }
+                }
+            }
+            let mut ready: Vec<usize> = (0..n).filter(|&c| pending[c] == 0).collect();
+            let mut peeled = 0;
+            while let Some(c) = ready.pop() {
+                peeled += 1;
+                for &p in &parents[c] {
+                    pending[p as usize] -= 1;
+                    if pending[p as usize] == 0 {
+                        ready.push(p as usize);
+                    }
+                }
+            }
+            let cyclic = peeled < n;
+
+            let mut search = Search {
+                n,
+                ids,
+                co_occurrences: &co_occurrences,
+                max_arity: max_arity.unwrap_or(usize::MAX),
+                cross_arity: false,
+                hole_if_empty: true,
+                hole_if_distinct: false,
+                exact_order: cyclic,
+                co_mode: 0,
+                class_start,
+                node_op,
+                node_kid_start,
+                node_kid_len,
+                node_kids,
+                class_simple,
+                co_cache: vec![0; n * n],
+                value: vec![UNVISITED; n * n],
+                set_start: vec![0],
+                set_len: vec![0],
+                set_data: Vec::new(),
+                scratch: Vec::new(),
+                hole_buf: Vec::new(),
+                terms: Terms::default(),
+            };
+
+            for a in 0..n {
+                for b in 0..n {
+                    if search.has_same_op(a, b) {
+                        search.visit(a * n + b);
+                    }
+                }
+            }
