+            // Collect every term stored for some state.
+            let mut used = vec![false; search.terms.op.len()];
+            for &t in &search.set_data {
+                used[t as usize] = true;
+            }
+
+            // Normalize: holes become pattern variables in order of first occurrence.
+            fn emit(terms: &Terms, t: u32, holes: &[u32], out: &mut Vec<u32>) {
+                let op = terms.op[t as usize];
+                if op == NONE {
+                    let state = terms.holes_of(t)[0];
+                    let index = holes.iter().position(|&h| h == state).unwrap();
+                    out.push(NONE - 1 - index as u32);
+                } else {
+                    let kids = terms.kids_of(t);
+                    out.push(op);
+                    out.push(kids.len() as u32);
+                    for &kid in kids {
+                        emit(terms, kid, holes, out);
+                    }
+                }
+            }
+            let mut normalized: FxMap<Vec<u32>, ()> = FxMap::default();
+            let mut max_holes = 0;
+            let mut tokens = Vec::new();
+            for t in 0..search.terms.op.len() as u32 {
+                if !used[t as usize] || search.terms.op[t as usize] == NONE {
+                    continue;
+                }
+                let holes = search.terms.holes_of(t);
+                if !learn_constants && holes.is_empty() {
+                    continue;
+                }
+                if max_arity.map_or(false, |limit| holes.len() > limit) {
+                    continue;
+                }
+                max_holes = std::cmp::max(max_holes, holes.len());
+                tokens.clear();
+                emit(&search.terms, t, holes, &mut tokens);
+                if !normalized.contains_key(&tokens[..]) {
+                    normalized.insert(tokens.clone(), ());
+                }
+            }
+            let vars: Vec<Var> = (0..max_holes)
+                .map(|i| format!("?x{}", i).parse().unwrap_or_else(|_| unreachable!()))
+                .collect();
+            fn build<Op: Arity + Clone + Debug>(
+                tokens: &[u32],
+                pos: &mut usize,
+                ops: &[Op],
+                vars: &[Var],
+            ) -> PartialExpr<Op, Var> {
+                let token = tokens[*pos];
+                *pos += 1;
+                if token >= NONE - 64 {
+                    PartialExpr::Hole(vars[(NONE - 1 - token) as usize])
+                } else {
+                    let len = tokens[*pos] as usize;
+                    *pos += 1;
+                    let kids: Vec<_> = (0..len).map(|_| build(tokens, pos, ops, vars)).collect();
+                    PartialExpr::from(AstNode::new(ops[token as usize].clone(), kids))
+                }
+            }
+            // Candidates in their final order.
+            let mut cands: Vec<(PartialExpr<Op, Var>, Vec<u32>)> = normalized
+                .into_iter()
+                .map(|(tokens, ())| (build(&tokens, &mut 0, &ops, &vars), tokens))
+                .collect();
