+                op: Vec<u32>,
+                kid_start: Vec<u32>,
+                kid_len: Vec<u32>,
+                kids: Vec<u32>,
+            }
+
+            fn parse_pat(tokens: &[u32], pos: &mut usize, pat: &mut Pat) -> u32 {
+                let id = pat.op.len() as u32;
+                let token = tokens[*pos];
+                *pos += 1;
+                pat.op.push(token);
+                pat.kid_start.push(0);
+                pat.kid_len.push(0);
+                if token < NONE - 64 {
+                    let len = tokens[*pos] as usize;
+                    *pos += 1;
+                    let kids: Vec<u32> = (0..len).map(|_| parse_pat(tokens, pos, pat)).collect();
+                    pat.kid_start[id as usize] = pat.kids.len() as u32;
+                    pat.kid_len[id as usize] = len as u32;
+                    pat.kids.extend(kids);
+                }
+                id
+            }
+
+            /// Enumerates the substitutions under which the pending pattern
+            /// nodes of `todo` are represented by their paired e-classes.
+            fn find(
+                search: &Search<'_>,
+                pat: &Pat,
+                todo: &mut Vec<(u32, u32)>,
+                subst: &mut [u32; 2],
+                out: &mut Vec<[u32; 2]>,
+            ) {
+                let (p, c) = match todo.pop() {
+                    Some(next) => next,
+                    None => {
+                        out.push(*subst);
+                        return;
+                    }
+                };
