+                if token >= NONE - 64 {
+                    let v = (NONE - 1 - token) as usize;
+                    if subst[v] == NONE {
+                        subst[v] = c;
+                        find(search, pat, todo, subst, out);
+                        subst[v] = NONE;
+                    } else if subst[v] == c {
