+            // would: the first candidate of minimal size in candidate order.
+            // Equivalent candidates abound when equations make the e-graph
+            // cyclic, so only then is this worth its matching cost.
+            let mut keep: Option<Vec<bool>> = if cyclic && max_holes <= 2 {
+                Some(vec![false; cands.len()])
+            } else {
+                None
+            };
+            if let Some(keep) = keep.as_mut() {
