+                let mut todo = Vec::new();
+                let mut out = Vec::new();
+                for (index, (_, tokens)) in cands.iter().enumerate() {
+                    let mut pat = Pat::default();
+                    parse_pat(tokens, &mut 0, &mut pat);
+                    let nvars = pat
+                        .op
+                        .iter()
+                        .filter(|&&t| t >= NONE - 64)
+                        .map(|&t| (NONE - t) as usize)
+                        .max()
+                        .unwrap_or(0);
+                    let mut key = Vec::new();
+                    for c in 0..search.n {
