+                            }
+                            key.push((class, actuals[0], actuals[1]));
+                        }
+                    }
+                    key.sort_unstable();
+                    let size = pat.op.len();
+                    match groups.get(&key) {
+                        Some(&(best, _)) if best <= size => {}
+                        _ => {
+                            groups.insert(key, (size, index));
+                        }
+                    }
+                }
+                for &(_, index) in groups.values() {
+                    keep[index] = true;
+                }
+            }
+            let nontrivial_aus: BTreeSet<PartialExpr<Op, Var>> = match keep {
+                Some(keep) => cands
+                    .into_iter()
+                    .zip(keep)
+                    .filter(|(_, kept)| *kept)
+                    .map(|((au, _), _)| au)
+                    .collect(),
+                None => cands.into_iter().map(|(au, _)| au).collect(),
+            };
+            LearnedLibrary {
+                nontrivial_aus,
+                marker: std::marker::PhantomData,
+            }
             // FRONTIER_EDIT_END: candidate generation
